<?php

declare(strict_types=1);

namespace Ashio\OpenProvider\Tests\Tools\Generate;

use Ashio\OpenProvider\Tools\Generate\GenerateCommand;
use PHPUnit\Framework\TestCase;

/**
 * `tools/generate models` owns src/Model: it writes what the spec yields, removes generated files
 * the spec no longer yields, and never touches (or accepts) a hand-written file there.
 */
final class GenerateModelsCommandTest extends TestCase
{
    private string $root;

    protected function setUp(): void
    {
        $this->root = sys_get_temp_dir() . '/op-generate-' . bin2hex(random_bytes(6));
        mkdir($this->root . '/spec', 0o777, true);
        file_put_contents($this->root . '/spec/openprovider.json', json_encode(ModelGeneratorTest::spec(), JSON_THROW_ON_ERROR));
    }

    protected function tearDown(): void
    {
        $files = new \RecursiveIteratorIterator(
            new \RecursiveDirectoryIterator($this->root, \FilesystemIterator::SKIP_DOTS),
            \RecursiveIteratorIterator::CHILD_FIRST,
        );
        foreach ($files as $file) {
            self::assertInstanceOf(\SplFileInfo::class, $file);
            $file->isDir() ? rmdir($file->getPathname()) : unlink($file->getPathname());
        }
        rmdir($this->root);
    }

    public function testItWritesTheModelsAndThenFindsThemUpToDate(): void
    {
        [$code, $out] = $this->generate(['models']);
        self::assertSame(0, $code);
        self::assertStringContainsString('4 files', $out);
        self::assertFileExists($this->root . '/src/Model/Domain/DomainThing.php');
        self::assertFileExists($this->root . '/src/Model/ModelMap.php');

        [$code, $out] = $this->generate(['models', '--check']);
        self::assertSame(0, $code, $out);
        self::assertStringContainsString('up to date', $out);
    }

    public function testCheckNamesAnEditedFileAndWritingRestoresIt(): void
    {
        $this->generate(['models']);
        $file = $this->root . '/src/Model/Domain/DomainThing.php';
        file_put_contents($file, "// edited by hand\n", FILE_APPEND);

        [$code, , $err] = $this->generate(['models', '--check']);
        self::assertSame(1, $code);
        self::assertStringContainsString('Domain/DomainThing.php', $err);

        $this->generate(['models']);
        self::assertSame(0, $this->generate(['models', '--check'])[0]);
    }

    public function testAGeneratedFileTheSpecNoLongerYieldsIsReportedAndRemoved(): void
    {
        $this->generate(['models']);
        $stale = $this->root . '/src/Model/Billing/BillingGone.php';
        mkdir(dirname($stale));
        file_put_contents($stale, "<?php\n/** @generated by `php tools/generate models` from spec/openprovider.json. Do not edit. */\n");

        [$code, , $err] = $this->generate(['models', '--check']);
        self::assertSame(1, $code);
        self::assertStringContainsString('Billing/BillingGone.php', $err);

        [$code, $out] = $this->generate(['models']);
        self::assertSame(0, $code);
        self::assertStringContainsString('removed 1', $out);
        self::assertFileDoesNotExist($stale);
        self::assertDirectoryDoesNotExist(dirname($stale));
    }

    public function testAHandWrittenFileInSrcModelIsRefusedAndKept(): void
    {
        $this->generate(['models']);
        $manual = $this->root . '/src/Model/Domain/Helper.php';
        file_put_contents($manual, "<?php\n");

        [$code, , $err] = $this->generate(['models']);
        self::assertSame(2, $code);
        self::assertStringContainsString('Domain/Helper.php is not generated', $err);
        self::assertFileExists($manual);

        self::assertSame(1, $this->generate(['models', '--check'])[0]);
    }

    public function testASpecTheGeneratorRefusesExitsWithTwo(): void
    {
        file_put_contents($this->root . '/spec/openprovider.json', '{');

        [$code, , $err] = $this->generate(['models']);
        self::assertSame(2, $code);
        self::assertStringContainsString('not valid JSON', $err);
    }

    /**
     * @param list<string> $arguments
     *
     * @return array{int, string, string}
     */
    private function generate(array $arguments): array
    {
        $out = fopen('php://memory', 'w+');
        $err = fopen('php://memory', 'w+');
        self::assertIsResource($out);
        self::assertIsResource($err);
        $code = GenerateCommand::run($arguments, $this->root, $out, $err);
        rewind($out);
        rewind($err);

        return [$code, (string) stream_get_contents($out), (string) stream_get_contents($err)];
    }
}
